Translate("zhCN", "lakeshire", {
	title = "湖畔镇",
	sections = {
		{
			title = "概述",
			text = [=[湖畔镇坐落在{link:lake-everstill}止水湖{/link}西岸，是一座有着石屋、热闹旅店、镇公所和马厩的城镇。它由{link:magistrate-solomon}所罗门镇长{/link}及其法庭治理，由{link:marshal-marris}治安官马瑞斯{/link}和一小支{link:stormwind-city}暴风城{/link}驻军守卫。如今，路障封住了它的北缘。{link:foreman-oslow}工头奥斯洛{/link}的工人们正在努力重建止水湖大桥，那座桥在{link:blackrock-clan}黑石兽人{/link}上一次进攻时被摧毁。旅店是城镇的中心。厨师布琳娜在那里用她能找到的东西做饭，酒保在等待一批永远不会到来的酒水，人们谈论的全是{link:orcs}兽人{/link}、{link:gnolls}豺狼人{/link}和暴风城承诺的援助。]=],
		},
	},
})

Translate("zhCN", "lake-everstill", {
	title = "止水湖",
	aliases = { "止水" },
	sections = {
		{
			title = "概述",
			text = [=[止水湖占据着{link:redridge-mountains}赤脊山{/link}的中心，在红色山岭下清澈湛蓝。湖中的斑点太阳鱼长久以来一直是{link:lakeshire}湖畔镇{/link}渔夫的骄傲。如今，大批{link:murlocs}鱼人{/link}来到湖岸，抛下它们简陋的锚，将鱼据为己有。码头管理员觉得在离海这么远的地方见到它们很奇怪，他怀疑它们是在逃避什么。水下埋藏的不只是鱼。{link:blackrock-clan}黑石兽人{/link}袭击一艘从毁坏的桥边渡湖的船时，船上的货物沉入了湖底，湖水至今仍将其留存。]=],
		},
	},
})

Translate("zhCN", "stonewatch-keep", {
	title = "石堡要塞",
	aliases = { "石堡" },
	sections = {
		{
			title = "概述",
			text = [=[石堡要塞是为王室守卫{link:redridge-mountains}赤脊山{/link}东部地区的堡垒。一小支{link:stormwind-city}暴风城{/link}驻军守卫着它，直到{link:blackrock-clan}黑石兽人{/link}在{link:morganth}大魔导师杜内{/link}黑暗魔法的加持下到来。{link:orcs}兽人{/link}作战之凶残，幸存者至今仍在谈论，要塞陷落了。如今它的城墙庇护着军阀{link:gath-ilzogg}加塞尔佐格{/link}和他的副官们，兽人从那里向北、向西袭击{link:lakeshire}湖畔镇{/link}。{link:magistrate-solomon}所罗门镇长{/link}认为，夺回要塞是王国必须完成的第一件事。]=],
		},
	},
})

Translate("zhCN", "stonewatch-tower", {
	title = "石堡高塔",
	sections = {
		{
			title = "概述",
			text = [=[石堡高塔是矗立在{link:stonewatch-keep}石堡要塞{/link}旁的瞭望塔。与要塞不同，它在战斗中完好无损，{link:orcs}兽人{/link}如今将它用作俯瞰{link:lakeshire}湖畔镇{/link}道路的瞭望哨。塔顶的木桶之间，躺着一个被遗忘的罐子，里面曾装过一种难闻的{link:brewnall-village}烈酒{/link}。高阶法师{link:theocritus}塞欧克瑞图斯{/link}选择了这个罐子来藏匿他的一枚符文，好让他的占卜之眼能够窥探要塞中人的心思。]=],
		},
	},
})

Translate("zhCN", "stonewatch-falls", {
	title = "石堡瀑布",
	sections = {
		{
			title = "概述",
			text = [=[在{link:stonewatch-keep}石堡{/link}下方，排出{link:lake-everstill}止水湖{/link}之水的河流沿山坡奔流而下，在东部丘陵中汇成一个深潭。这就是石堡瀑布。{link:murlocs}鱼人{/link}在河岸边搭起了小屋，在这片水域捕鱼，就像它们的同类在大湖岸边所做的那样。瀑布上方矗立着失陷要塞的城墙。瀑布位于石堡的{link:orcs}兽人{/link}和{link:galardell-valley}加拉德尔山谷{/link}的{link:gnolls}豺狼人{/link}之间，如今很少有{link:lakeshire}湖畔镇{/link}的人会走到这么远的东边。]=],
		},
	},
})

Translate("zhCN", "tower-of-ilgalar", {
	title = "伊尔加拉之塔",
