	sections = {
		{
			title = "概述",
			text = [=[伊尔加拉之塔耸立在{link:redridge-mountains}赤脊山{/link}东北部的丘陵中。它是术士{link:morganth}大魔导师杜内{/link}的巢穴，他在背叛{link:orcs}兽人{/link}盟友后建起了这座塔。{link:shadowhide-gnolls}暗皮豺狼人{/link}守卫着通往塔楼的道路，塔中的大厅里挂着巨龙的骸骨，其用途外人无从猜测。在塔墙附近，一尊古老的狮子雕像孤独地守望了数十年。在遥远的西方，法师{link:theocritus}塞欧克瑞图斯{/link}通过{link:tower-of-azora}他自己塔中{/link}的阿祖拉之眼注视着这座塔。]=],
		},
	},
})

Translate("zhCN", "galardell-valley", {
	title = "加拉德尔山谷",
	aliases = { "加拉德尔" },
	sections = {
		{
			title = "概述",
			text = [=[加拉德尔山谷位于{link:redridge-mountains}赤脊山{/link}东北部，环绕着{link:tower-of-ilgalar}伊尔加拉之塔{/link}的塔基。这里是为术士{link:morganth}大魔导师杜内{/link}效力的{link:shadowhide-gnolls}暗皮豺狼人{/link}的地盘。它们的营地遍布{link:stranglethorn-vale}山谷{/link}，它们的首领{link:lieutenant-fangore}范高雷将军{/link}在山谷北部驻守。它们之中行走着施展术士暗影魔法的暗影编织者。误入此地的旅人很少只遇到一只{link:gnolls}豺狼人{/link}。暗皮豺狼人对求救呼声的响应比山中任何其他族群都快，方格雷一声呼唤，整个山谷都会奔涌而来。]=],
		},
	},
})

Translate("zhCN", "alther-s-mill", {
	title = "奥瑟尔伐木场",
