	aliases = { "瑞斯班" },
	sections = {
		{
			title = "概述",
			text = [=[瑞斯班洞穴深入{link:lakeshire}湖畔镇{/link}以北的山麓。它们得名于巴尔特·瑞斯班，他最先发现了洞壁上的{link:mirkfallon-lake}暗色{/link}矿石。湖畔镇过去一直储存着这种矿石，因为抄写员看重它的颜色，用来制作墨水。如今{link:redridge-gnolls}赤脊山豺狼人{/link}住在洞穴里，它们的苦工为自己开采矿石。{link:foreman-oslow}工头奥斯洛{/link}的工人们忙于城镇的防御，无暇去取。湖畔镇一个麦酒家族的{link:dwarves}矮人{/link}将这些洞穴变成了对战士胆量的考验。]=],
		},
	},
})

Translate("zhCN", "redridge-canyons", {
	title = "赤脊峡谷",
	sections = {
		{
			title = "概述",
			text = [=[赤脊峡谷穿过{link:lakeshire}湖畔镇{/link}以北的丘陵，位于通往{link:burning-steppes}燃烧平原{/link}的道路上。这里是{link:redridge-gnolls}赤脊山豺狼人{/link}的猎场。它们的蛮兵和秘法师在镇上马厩上方的山脊间游荡，偷走任何走失的马匹。它们的首领{link:yowler}犹勒{/link}在峡谷中有一个巢穴，在寂静的夜晚，整个城镇都能听到他的族群在山中嚎叫。更北面，靠近山口的地方，{link:blackrock-clan}黑石兽人{/link}扎下了营地，于是湖畔镇被{link:gnolls}豺狼人{/link}和{link:orcs}兽人{/link}团团围住。]=],
		},
	},
})

Translate("zhCN", "lakeridge-highway", {
	title = "湖边大道",
	sections = {
		{
			title = "概述",
			text = [=[湖边大道从{link:lakeshire}湖畔镇{/link}的南桥向东延伸，沿着{link:lake-everstill}止水湖{/link}南岸通往{link:stonewatch-keep}石堡{/link}。它为贸易而修建，连接着城镇与山脉的东部地区。自从{link:orcs}兽人{/link}占领要塞以来，很少有马车再走这条路。{link:gnolls}豺狼人{/link}沿着南方的道路扎营，{link:murlocs}鱼人{/link}在湖岸上猎食，秃鹫在山丘上空盘旋。{link:deputy-feldon}菲尔顿副队长{/link}在大道西端值守，并为任何关于沿途集结之敌的消息付钱。]=],
		},
	},
})

Translate("zhCN", "three-corners", {
	title = "三角路口",
	sections = {
		{
			title = "概述",
			text = [=[三角路口是{link:redridge-mountains}赤脊山{/link}西部边缘的{link:the-crossroads}十字路口{/link}。从这里，一条路通往{link:lakeshire}湖畔镇{/link}，一条通往{link:elwynn-forest}艾尔文{/link}的{link:goldshire}闪金镇{/link}，一条通往{link:duskwood}暮色森林{/link}的{link:darkshire}夜色镇{/link}。{link:guard-parker}卫兵队长帕克{/link}在通往暮色森林的那段路上巡逻。如今，这个路口已成为一处贸易场所。{link:azeroth}艾泽拉斯{/link}贸易局，一个商人组成的公司，在这里设立了它的地方货栈，有军需官、职员、骡子和一堆等待检查的板条箱。它的信使从各地带回空箱子。]=],
		},
	},
})

Translate("zhCN", "render-s-camp", {
	title = "撕裂者营地",
	aliases = { "撕裂者之石" },
	sections = {
		{
			title = "概述",
			text = [=[撕裂者营地是{link:blackrock-clan}黑石兽人{/link}在{link:redridge-mountains}赤脊山{/link}西北部的营地，就在通往{link:burning-steppes}燃烧平原{/link}的山口以西。{link:orcs}兽人{/link}大军中率领各个部队的勇士在这里驻扎。营地后面是撕裂者之石，那是一个巨大的洞穴，兽人在那里关押他们的俘虏。其中有一名{link:stormwind-city}暴风城{/link}的下士，他在{link:stonewatch-keep}石堡要塞{/link}的战斗中被拖走，他的名字至今仍张贴在{link:lakeshire}湖畔镇{/link}旅店外。{link:blackrock-mountain}黑石{/link}追踪者在周围的丘陵中游荡，监视着从南方而来的道路。]=],
		},
	},
})

Translate("zhCN", "render-s-valley", {
	title = "撕裂者山谷",
	sections = {
