Translate("zhCN", "blackrock-clan", {
	title = "黑石氏族",
	aliases = { "黑石兽人", "黑石" },
	sections = {
		{
			title = "概述",
			text = [=[黑石氏族是{link:orcs}兽人{/link}中最古老、最好战的氏族之一。他们是旧{link:horde}部落{/link}的中坚，为它贡献了两位大酋长。在部落战败很久之后，黑石兽人仍保持着古老的战争之道，他们从未与{link:humans}人类{/link}讲和。]=],
		},
		{
			title = "历史",
			text = [=[在{link:first-war}第一次战争{/link}中，黑石氏族的酋长黑手作为大酋长领导{link:horde}部落{/link}，尽管在他背后操纵的另有其人。他被自己人杀死，那人是黑石战士{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}，后者随后率领部落征服了{link:stormwind-city}暴风城{/link}。在{link:second-war}第二次战争{/link}中，毁灭之锤杀死{link:anduin-lothar}安度因·洛萨{/link}之后，他的部落在{link:blackrock-mountain}黑石山{/link}被击溃。大部分{link:orcs}兽人{/link}被赶进了{link:internment-camps}收容所{/link}。逃脱的黑石兽人在以他们的名字命名的山中避难，从此一直占据着它的高处。]=],
		},
		{
			title = "在赤脊山",
			text = [=[如今，黑石兽人从{link:burning-steppes}燃烧平原{/link}南下。在军阀{link:gath-ilzogg}加塞尔佐格{/link}的率领下，借助{link:morganth}大魔导师杜内{/link}的黑暗魔法，他们夺取了{link:stonewatch-keep}石堡要塞{/link}，摧毁了{link:lake-everstill}止水湖{/link}大桥。他们的斥候伏击道路，他们的暗影法师携带着被恶魔污染的法球，他们的勇士在北部山口旁扎营。另一支战团从{link:render-s-valley}撕裂者山谷{/link}进入了遥远的东南部。然而他们深入王国太远，不得不在山中搜寻食物和武器，{link:lakeshire}湖畔镇{/link}希望将他们活活饿死。]=],
		},
		{
			title = "新的部落",
			text = [=[并非每一个黑石兽人都留在了氏族中。{link:eitrigg}艾瑞克{/link}曾为{link:blackrock-mountain}黑石{/link}酋长效力，后来他憎恨那些将他的族人引入歧途的恶魔崇拜者。如今他在{link:orgrimmar}奥格瑞玛{/link}为{link:thrall}萨尔{/link}效力，远离他旧氏族的大山。]=],
		},
	},
})

Translate("zhCN", "shadowhide-gnolls", {
	title = "暗皮豺狼人",
	aliases = { "暗皮" },
	sections = {
		{
			title = "概述",
			text = [=[暗皮是一个{link:gnolls}豺狼人{/link}氏族，居住在{link:redridge-mountains}赤脊山{/link}东北部的{link:galardell-valley}加拉德尔山谷{/link}。它们为术士{link:morganth}大魔导师杜内{/link}效力。它们的首领是{link:lieutenant-fangore}范高雷将军{/link}。它们的暗影编织者施展暗影魔法，它们的刺客在暗中出击，它们的杀戮者对{link:orcs}兽人{/link}和{link:humans}人类{/link}一视同仁地发动攻击。]=],
		},
		{
			title = "坠饰之缚",
			text = [=[每一个暗皮豺狼人都佩戴着一枚坠饰，{link:morganth}大魔导师杜内{/link}通过它与它们交谈。高阶法师{link:theocritus}塞欧克瑞图斯{/link}花了数月时间试图侵入这些坠饰。他已设法通过其中一些坠饰传递了一条讯息，他希望有朝一日能通过它们发动一次攻击，让每一个佩戴坠饰的{link:gnolls}豺狼人{/link}都动弹不得。]=],
		},
		{
			title = "律法之下",
			text = [=[{link:lakeshire}湖畔镇{/link}法庭宣判暗皮豺狼人犯有援助王国罪犯之罪，此罪当处死刑。{link:bailiff-conacher}拜里弗·科纳彻尔{/link}为它们的坠饰付钱作为证据，治安官还亲自悬赏{link:lieutenant-fangore}方格雷{/link}的首级。]=],
		},
		{
			title = "众人之敌",
			text = [=[暗皮豺狼人并不是{link:blackrock-clan}黑石兽人{/link}的朋友。当{link:morganth}大魔导师杜内{/link}背叛他的{link:orcs}兽人{/link}盟友时，他的{link:gnolls}豺狼人{/link}也随之倒戈，死在它们手中的兽人和{link:humans}人类{/link}一样多。]=],
		},
	},
})

Translate("zhCN", "redridge-gnolls", {
