	aliases = { "赤脊山族群" },
	sections = {
		{
			title = "概述",
			text = [=[赤脊山豺狼人是{link:redridge-mountains}赤脊山{/link}中古老的{link:gnolls}豺狼人{/link}族群，与为{link:morganth}大魔导师杜内{/link}效力的{link:shadowhide-gnolls}暗皮豺狼人{/link}截然不同。它们不为任何术士或{link:orcs}兽人{/link}效力。它们的蛮兵和秘法师在{link:lakeshire}湖畔镇{/link}以北的丘陵中游荡，它们的偷猎者和杂种豺狼人沿着南方道路扎营。它们的首领是{link:yowler}犹勒{/link}，他的巢穴在{link:redridge-canyons}赤脊峡谷{/link}，他的嚎叫声一直传到湖畔镇。]=],
		},
		{
			title = "习性",
			text = [=[赤脊山豺狼人夺取战争留下的无人看守之物。它们劫走了为{link:lake-everstill}止水湖{/link}大桥运铁的车队。它们从{link:lakeshire}湖畔镇{/link}的马厩偷马。它们搬进了{link:rethban-caverns}瑞斯班洞穴{/link}，它们的苦工在那里开采城镇过去开采的矿石。它们组织松散，但最尊重的是力量。{link:deputy-feldon}菲尔顿副队长{/link}希望，杀死它们最凶猛的鞭笞者能让其余的{link:gnolls}豺狼人{/link}待在山里。在瑞斯班，一只名叫阿尔多·泥爪的豺狼人率领着占据洞穴的族群。]=],
		},
	},
